export function validateBundledVisual(file,manifest){
 const p=file?.visualPublication;
 const pin=bundledVisualBindings.find(f=>f.visualPublication.packId===manifest.packId&&f.visualPublication.presentationRevision===manifest.presentationRevision&&f.visualPublication.assetId===p?.assetId);
 if(!pin||file.variants||file.deliveryRevision!==manifest.deliveryRevision||typeof file.deliveryRevision!=='string'||!/^(?!0{64}$)[a-f0-9]{64}$/.test(file.deliveryRevision)||Object.entries(pin).some(([k,v])=>k==='visualPublication'?Object.entries(v).some(([key,value])=>p?.[key]!==value):file[k]!==v))throw Error('Invalid bundled visual binding.');
 return file;
}
